"bio":"Party games, couch co-op and clips that make the whole group laugh.","handle":"zoe_avery","created_at":"2026-11-06T10:04:28.453328+00:00","avatar_path":"969d3d84-0bd4-581b-9321-05f027434932/c20a5770-5828-579a-a49a-5ac447c842f4.jpg","display_name":"Zoe Avery"},"size":21274},{"id":"0a8b2ca1-9e56-4843-828c-07f560fabd2a","label":"Development Alpha","before_row":{"id":"0a8b2ca1-9e56-4843-828c-07f560fabd2a","bio":"Mostly here for good game clips and relaxed co-op. Always up for one more round.","handle":"ethan_cole","created_at":"2026-11-03T09:47:26.1679+00:00","avatar_path":"0a8b2ca1-9e56-4843-828c-07f560fabd2a/4d5de38f-b6ac-4b56-926c-96242b997029.jpg","display_name":"Ethan Cole"},"after_row":{"id":"0a8b2ca1-9e56-4843-828c-07f560fabd2a","bio":"Mostly here for good game clips and relaxed co-op. Always up for one more round.","handle":"ethan_cole","created_at":"2026-11-03T09:47:26.1679+00:00","avatar_path":"0a8b2ca1-9e56-4843-828c-07f560fabd2a/4d5de38f-b6ac-4b56-926c-96242b997029.jpg","display_name":"Ethan Cole"},"size":22612},{"id":"25b18ddf-bf23-4744-bff9-03fd8c970a1c","label":"Development Beta","before_row":{"id":"25b18ddf-bf23-4744-bff9-03fd8c970a1c","bio":"Co-op nights, cozy builds and a playlist that never ends. Send me your favorite game clip.","handle":"maya_reed","created_at":"2026-11-03T09:47:36.641671+00:00","avatar_path":"25b18ddf-bf23-4744-bff9-03fd8c970a1c/894b4132-1888-4306-af6b-56f6f06eda0c.jpg","display_name":"Maya Reed"},"after_row":{"id":"25b18ddf-bf23-4744-bff9-03fd8c970a1c","bio":"Co-op nights, cozy builds and a playlist that never ends. Send me your favorite game clip.","handle":"maya_reed","created_at":"2026-11-03T09:47:36.641671+00:00","avatar_path":"25b18ddf-bf23-4744-bff9-03fd8c970a1c/894b4132-1888-4306-af6b-56f6f06eda0c.jpg","display_name":"Maya Reed"},"size":18984}]'::jsonb)
as x(id uuid, label text, before_row jsonb, after_row jsonb, size bigint);
do $avatars$
declare affected integer;
begin
  if (select count(distinct id) from expected_avatar_updates) <> 38
    or (select count(*) from expected_avatar_updates) <> 38 then
    raise exception 'Avatar replacement scope changed';
  end if;
  if (select count(*) from expected_avatar_updates where before_row<>after_row) <> 30 then
    raise exception 'Expected exactly 30 changed avatars';
  end if;
  perform p.id from public.profiles p join expected_avatar_updates e using(id) order by p.id for update of p;
  if (select count(*) from expected_avatar_updates e join public.profiles p using(id)
      join private.accounts a on a.user_id=p.id and a.cohort='development' and a.state='active'
      join private.development_accounts d on d.user_id=p.id and d.label=e.label
      where d.enabled and d.expires_at>now() and private.account_is_eligible(p.id)
        and to_jsonb(p)=e.before_row and e.before_row-'avatar_path'=e.after_row-'avatar_path'
) <> 38 then
    raise exception 'Avatar baseline or account eligibility changed';
  end if;
  if (select count(*) from expected_avatar_updates e
      join storage.objects o on o.bucket_id='avatars' and o.name=e.after_row->>'avatar_path'
        and o.owner_id=e.id::text
      join storage.buckets b on b.id=o.bucket_id and b.public=false where true
    and o.metadata->>'mimetype'='image/jpeg' and o.metadata->>'size'=e.size::text) <> 38 then
    raise exception 'Expected private avatar objects not found';
  end if;
  update public.profiles p set avatar_path=e.after_row->>'avatar_path'
    from expected_avatar_updates e where p.id=e.id and to_jsonb(p)=e.before_row and e.before_row<>e.after_row;
  get diagnostics affected = row_count;
  if affected <> 30 or (select count(*) from public.profiles p join expected_avatar_updates e using(id)
      where to_jsonb(p)=e.after_row) <> 38 then
    raise exception 'Avatar update count or profile mismatch';
  end if;
end $avatars$;
select count(*)::int as verified_profiles, count(*) filter(where before_row<>after_row)::int as changed_avatars from expected_avatar_updates;
commit;
